def count_median_pairs():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    count = 0
    for i in range(n):
        l, r = i, i
        while r < n and a[r] <= m:
            r += 1
        while l >= 0 and a[l] < m:
            l -= 1
        if l + 1 == r - 1 or (l + 1 == r and a[l] == m):
            count += max(0, min(r - l - 2, n - r))
    print(count)
```

