def count_median_pairs():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    left, right = 0, 0
    count = 0
    while right < n:
        if a[right] <= m:
            right += 1
        else:
            if (right - left) % 2 == 0 and a[(left + right) // 2] == m:
                count += right - left
            elif (right - left) % 2 == 1 and a[(left + right) // 2] >= m:
                count += right - left
            left += 1
    print(count)
