def solve(n, k, a):
    if sum(a) % 2 == 0 or n < k:
        return "NO"
    odd_count = sum(1 for x in a if x % 2 != 0)
    if odd_count < k:
        return "NO"
    result = []
    i = 0
    while len(result) < k - 1 and i < n:
        if a[i] % 2 != 0:
            result.append(i + 1)
            i += 1
        else:
            i += 1
    if len(result) == k - 1:
        return "YES\n" + ' '.join(map(str, result + [n]))
    else:
        return "NO"
