def process_input():
    mode, text = input().split()
    if mode == 'E':
        return encode(text)
    elif mode == 'D':
        return decode(text)

def encode(s):
    encoded = ''
    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i] == s[i+1]:
            i += 1
            count += 1
        encoded += s[i] + str(count)
        i += 1
    return encoded

def decode(s):
    decoded = ''
    for i in range(0, len(s), 2):
        char = s[i]
        count = int(s[i+1])
        decoded += char * count
    return decoded

