def count_ways(n, l, r, x, c):
    dp = [[0] * (r + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(l, r + 1):
            if j >= c[i - 1]:
                dp[i][j] = dp[i - 1][j]
                if j - x >= l:
                    dp[i][j] += dp[i - 1][j - x]
    return sum(dp[n][l:r + 1])

