def min_traffic(n, m, k, w):
    levels = [list(input()) for _ in range(k)]
    dp = [[float('inf')] * (1 << k) for _ in range(1 << k)]
    prev = [[-1] * (1 << k) for _ in range(1 << k)]

    def dfs(state, i):
        if state == (1 << k) - 1:
            return 0
        if dp[state][i] != float('inf'):
            return dp[state][i]
        for j in range(i + 1, k):
            if ((state >> j) & 1) == 0:
                diff = sum(c1 != c2 for c1, c2 in zip(levels[i], levels[j]))
                next_state = state | (1 << j)
                cost = dfs(state, j) + diff * w
                if cost < dp[next_state][i]:
                    dp[next_state][i] = cost
                    prev[next_state][i] = j
        return dp[state][i]

    min_cost = float('inf')
    for i in range(k):
        cost = dfs(1 << i, i)
        if cost < min_cost:
            min_cost = cost

    result = []
    state = (1 << k) - 1
    while state != 0:
        i = prev[state][i]
        result.append((i + 1, prev[state][i] + 1))
        state ^= (1 << i)

    print(min_cost)
    for x, y in result:
        print(x, y)

