def vasya(n, k, s):
    mod = 10**9 + 7
    dp = [[0] * (k+1) for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(1, n+1):
        for j in range(k+1):
            if j > 0 and s[i-1] != '0':
                dp[i][j] += dp[i-1][j-1]
            if j < k:
                dp[i][j+1] += dp[i-1][j]

    return sum(dp[n]) % mod

