        for i in range(n):
            for j in range(m):
                if not visited[i][j]:
                    dfs(i, j)
                    components.append(sum(a[i][j] for i in range(n) for j in range(m) if visited[i][j]))
        return len(components), sum(c * (c - 1) // 2 for c in components)
    def solve(k):
        components, total = count_components()
        if components == 0:
            return 0
        if k < components - 1 or total > k:
            return -1
        return min(solve(k - 1), solve(k))
    print(solve(k))

