def solve_bar_code():
    n = int(input())
    vertical_specs = [list(map(int, input().split())) for _ in range(n)]
    horizontal_specs = [list(map(int, input().split())) for _ in range(n)]

    # Initialize grid with all zeros
    grid = [[0] * (n + 1) for _ in range(n)]

    # Fill vertical bars based on specifications
    for i in range(n):
        spec = vertical_specs[i]
        if sum(spec) > 0:
            curr = 0
            for j in range(1, n + 1):
                if curr < len(spec) and grid[i][j - 1] == 0:
                    grid[i][j] = 1
                    curr += 1
                    if curr == spec[curr - 1]:
                        curr = 0

    # Fill horizontal bars based on specifications
    for j in range(n):
        spec = horizontal_specs[j]
        if sum(spec) > 0:
            curr = 0
            for i in range(1, n + 1):
                if curr < len(spec) and grid[i - 1][j] == 0:
                    grid[i][j] = 1
                    curr += 1
                    if curr == spec[curr - 1]:
                        curr = 0

    # Print vertical bars
    for row in grid[:-1]:
        print(''.join(str(cell) for cell in row))

    # Print horizontal bars
    for i in range(n):
        print(''.join(str(grid[j][i]) for j in range(n)))

solve_bar_code()
