def simulate_planets():
    n, nx, ny, nz = map(int, input().split())
    planetoids = []
    for _ in range(n):
        m, x, y, z, vx, vy, vz = map(int, input().split())
        planetoids.append((m, (x % nx, y % ny, z % nz), (vx, vy, vz)))

    def update_location(planet):
        x, y, z, vx, vy, vz = planet[1] + planet[2]
        return (planet[0], (x % nx, y % ny, z % nz), (vx, vy, vz))

    def find_collisions(planets):
        collisions = []
        for i in range(len(planets)):
            for j in range(i + 1, len(planets)):
                if planets[i][1] == planets[j][1]:
                    m = planets[i][0] + planets[j][0]
                    v = tuple(sum(p) // 2 for p in zip(planets[i][2], planets[j][2]))
                    collisions.append((m, planets[i][1], v))
        return collisions

    def merge_collisions(collisions):
        merged = []
        while collisions:
            m, loc, v = collisions.pop()
            if not merged or merged[-1][1] != loc:
                merged.append((m, loc, v))
            else:
                merged[-1] = (merged[-1][0] + m, loc, tuple(sum(p) // 2 for p in zip(merged[-1][2], v)))
        return merged

    planets = planetoids
    while True:
        updated_planets = [update_location(planet) for planet in planets]
        collisions = find_collisions(updated_planets)
        if not collisions:
            break
        merged_collisions = merge_collisions(collisions)
        planets = [(m, loc, v) for m, loc, v in updated_planets if (m, loc, v) not in merged_collisions] + merged_collisions

    print(len(planets))
    for i, planet in enumerate(sorted(planets, key=lambda x: (-x[0], x[1]), reverse=True)):
        print(f"P{i}: {planet}")

