    nails = [tuple(map(int, input().split())) for _ in range(n)]
    directions = input()

    def area(x1, y1, x2, y2):
        return abs(x1 - x2) * abs(y1 - y2)

    areas = []
    prev_nail = None
    for direction in directions:
        if direction == 'L':
            curr_nail = min(nails, key=lambda x: x[0])
        elif direction == 'R':
            curr_nail = max(nails, key=lambda x: x[0])
        elif direction == 'U':
            curr_nail = max(nails, key=lambda x: x[1])
        else:
            curr_nail = min(nails, key=lambda x: x[1])

        if prev_nail is not None:
            areas.append(area(*prev_nail, *curr_nail))

        nails.remove(curr_nail)
        prev_nail = curr_nail

    print('\n'.join(map(lambda x: '{:.1f}'.format(x), areas)))

