def max_onions_protected():
    N, M, K = map(int, input().split())
    onions = [tuple(map(int, input().split())) for _ in range(N)]
    posts = [tuple(map(int, input().split())) for _ in range(M)]

    def convex_hull(points):
        hull = []
        while len(hull) < 2 or points[-1] != hull[0]:
            hull.append(points.pop())
        while len(points) > 0:
            p1, p2 = hull[-1], hull[0]
            dx, dy = p2[0] - p1[0], p2[1] - p1[1]
            n = len(points)
            for i in range(n):
                x, y = points[i][0] - p1[0], points[i][1] - p1[1]
                if dy * x > dx * y:
                    points.insert(i, points.pop())
                    break
            hull.append(points.pop())
        return hull

    def count_onions_in_hull(hull):
        count = 0
        for onion in onions:
            if all(onion[i] >= hull[i][j] for i in range(2) for j in (0, 1)):
                count += 1
        return count

    def dfs(posts, K, idx=0):
        if K == 0 or idx == len(posts):
            return count_onions_in_hull(convex_hull(posts))
        else:
            return max(dfs(posts[:idx] + posts[idx+1:], K-1), dfs(posts, K, idx+1))

    print(dfs(posts, K))

